CREATE TABLE IF NOT EXISTS countries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_name text NOT NULL UNIQUE, iso_code text, region text NOT NULL, legal_system text, investment_climate text, foreign_ownership_summary text, local_director_required boolean NOT NULL DEFAULT false, land_ownership_summary text, customary_rights_framework text, regulatory_complexity text NOT NULL DEFAULT 'Unassessed', jurisdiction_status text NOT NULL DEFAULT 'Research', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS jurisdiction_requirements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_id uuid NOT NULL REFERENCES countries(id) ON DELETE CASCADE, requirement_type text NOT NULL, requirement_name text NOT NULL, authority_name text, mandatory boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'Research Required', due_trigger text, owner_role text, evidence_url text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS country_entry_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_id uuid NOT NULL REFERENCES countries(id) ON DELETE CASCADE, proposed_entity_type text NOT NULL, business_activity text NOT NULL, entry_status text NOT NULL DEFAULT 'Not Started', legal_review_status text NOT NULL DEFAULT 'Pending', tax_review_status text NOT NULL DEFAULT 'Pending', ownership_review_status text NOT NULL DEFAULT 'Pending', land_rights_review_status text NOT NULL DEFAULT 'Pending', community_rights_review_status text NOT NULL DEFAULT 'Pending', licensing_review_status text NOT NULL DEFAULT 'Pending', risk_score numeric(5,2), recommendation text, reviewed_by text, reviewed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS country_regulatory_bodies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_id uuid NOT NULL REFERENCES countries(id) ON DELETE CASCADE, body_name text NOT NULL, regulator_type text NOT NULL, website_url text, scope text, status text NOT NULL DEFAULT 'Reference', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS country_compliance_calendar (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), country_id uuid NOT NULL REFERENCES countries(id) ON DELETE CASCADE, obligation_name text NOT NULL, frequency text, due_date date, trigger_rule text, responsible_role text, status text NOT NULL DEFAULT 'Planned', evidence_record_id uuid, notes text, created_at timestamptz NOT NULL DEFAULT now());
